parameters.jsCode:
const run = $input.first().json;

// Get the complete report from Career Coach (Orchestrator)
const report = String(run.output ?? '').trim();

// Required sections from the three specialist agents
const requiredSections = [
  'CV Match Analysis',
  'Tailored Cover Letter',
  'Interview Preparation',
];

// Check whether all specialist sections exist
const missingSections = requiredSections.filter(
  section => !report.includes(section)
);

// Count the specialist sections found
const specialistsUsed =
  requiredSections.length - missingSections.length;

// Build the final report
const finalReport = report || 
  '# Job Application Preparation Report\n\nNo report was returned by Career Coach. Please execute the previous node again.';

// Return data for the Markdown and Gmail nodes
return [
  {
    json: {
      report: finalReport,
      specialistsUsed,
      complete: missingSections.length === 0,
      missingSections,
      candidateName:
        $('Prepare Application').first().json.Name ?? '',
      jobDescription:
        $('Prepare Application').first().json['job description'] ?? '',
    },
  },
];
